package main

import (
	"os"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/records"
	"github.com/coalaura/outboxd/internal/sign"
)

func dns() error {
	cfg, _, err := config.Ensure()
	if err != nil {
		return err
	}

	signer, _, err := sign.Ensure(cfg)
	if err != nil {
		return err
	}

	_, body, err := records.Write(cfg, signer.Record())
	if err != nil {
		return err
	}

	_, err = os.Stdout.Write(body)

	return err
}

package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"sync"
	"syscall"

	"github.com/coalaura/outboxd/internal/certs"
	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/deliver"
	"github.com/coalaura/outboxd/internal/disk"
	"github.com/coalaura/outboxd/internal/queue"
	"github.com/coalaura/outboxd/internal/records"
	"github.com/coalaura/outboxd/internal/sign"
	"github.com/coalaura/outboxd/internal/smtpd"
	"github.com/coalaura/plain"
)

var log = plain.New(plain.WithDate(plain.RFC3339Local))

func main() {
	arguments := os.Args[1:]

	if len(arguments) == 0 {
		log.MustFail(serve())

		return
	}

	switch arguments[0] {
	case "user":
		log.MustFail(user(arguments[1:]))
	case "dns":
		log.MustFail(dns())
	default:
		log.MustFail(fmt.Errorf("unknown command %q, expected user or dns", arguments[0]))
	}
}

func serve() error {
	log.Println("Loading config...")

	cfg, created, err := config.Ensure()
	if err != nil {
		return err
	}

	if created {
		log.Println("Created default config")
	}

	log.Println("Ensuring data directory...")

	err = disk.Mkdir(cfg.Server.DataDirectory)
	if err != nil {
		return err
	}

	for _, warning := range cfg.Warnings() {
		log.Warnln(warning)
	}

	err = cfg.IsReady()
	if err != nil {
		return err
	}

	log.Println("Ensuring DKIM keys...")

	signer, generated, err := sign.Ensure(cfg)
	if err != nil {
		return err
	}

	if generated {
		log.Println("Generated DKIM key")
	}

	log.Println("Ensuring TLS certificates...")

	keeper, generated, err := certs.Ensure(cfg)
	if err != nil {
		return err
	}

	if generated {
		log.Println("Generated self-signed TLS certificate")
	}

	log.Println("Writing DNS instructions...")

	path, _, err := records.Write(cfg, signer.Record())
	if err != nil {
		return err
	}

	log.Printf("Wrote DNS instructions to %s\n", path)

	spool, err := queue.Open(cfg.ResolvePath("queue"))
	if err != nil {
		return err
	}

	log.Println("Starting server...")

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	submission := smtpd.New(cfg, keeper, signer, spool, log)

	err = submission.Listen()
	if err != nil {
		return err
	}

	deliverer := deliver.New(cfg, spool, log)

	var (
		wg   sync.WaitGroup
		errs [2]error
	)

	wg.Go(func() {
		defer stop()

		errs[0] = submission.Run(ctx)
	})

	wg.Go(func() {
		defer stop()

		errs[1] = deliverer.Run(ctx)
	})

	log.Println("Server ready")

	wg.Wait()

	log.Warnln("Stopped")

	return errors.Join(errs[0], errs[1])
}

package main

import (
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/passwd"
	"github.com/goccy/go-yaml"
)

func user(arguments []string) error {
	if len(arguments) < 2 || arguments[0] != "add" {
		return errors.New("usage: outboxd user add <username> [sender...]")
	}

	username := arguments[1]

	senders := arguments[2:]
	if len(senders) == 0 {
		if !strings.Contains(username, "@") {
			return errors.New("provide at least one allowed sender address")
		}

		senders = []string{username}
	}

	password, generated, err := password()
	if err != nil {
		return err
	}

	hash, err := passwd.Hash(password)
	if err != nil {
		return err
	}

	entry := config.User{
		Username:       username,
		PasswordHash:   hash,
		AllowedSenders: senders,
		Enabled:        true,
	}

	err = entry.Validate()
	if err != nil {
		return err
	}

	block, err := yaml.MarshalWithOptions([]config.User{entry}, yaml.Indent(2))
	if err != nil {
		return err
	}

	var out strings.Builder

	out.Grow(len(block) + 512)

	if generated {
		fmt.Fprintf(&out, "\nGenerated password for %s\n\n  %s\n\n", entry.Username, password)
		out.WriteString("Store it now. It is shown once and never written to disk in plaintext.\n")
	}

	out.WriteString("\nAdd the following to the config:\n\nusers:\n")

	for line := range strings.SplitSeq(strings.TrimRight(string(block), "\n"), "\n") {
		fmt.Fprintf(&out, "  %s\n", line)
	}

	_, err = os.Stdout.WriteString(out.String())

	return err
}

// password reads a password from stdin when it is piped, so unattended setup
// never has to put a plaintext password in argv where ps can read it.
func password() (string, bool, error) {
	info, err := os.Stdin.Stat()
	if err != nil {
		return "", false, err
	}

	if info.Mode()&os.ModeCharDevice != 0 {
		// 26 base32 characters, ~120 bits after lowercasing.
		return strings.ToLower(rand.Text()), true, nil
	}

	body, err := io.ReadAll(io.LimitReader(os.Stdin, 1<<10))
	if err != nil {
		return "", false, err
	}

	supplied := strings.Trim(string(body), "\r\n")
	if supplied == "" {
		return "", false, errors.New("empty password on stdin")
	}

	return supplied, false, nil
}

package certs

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"os"
	"sync"
	"time"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/disk"
)

const reloadInterval = time.Minute

// Keeper serves the submission certificate and picks up renewals without a
// restart, which matters for ACME managed files.
type Keeper struct {
	certificateFile string
	privateKeyFile  string
	minimumVersion  uint16

	mu          sync.Mutex
	certificate *tls.Certificate
	stamp       time.Time
	checked     time.Time
}

// Ensure loads the submission certificate, generating a self-signed pair when
// tls.mode is self_signed and no files exist yet.
func Ensure(cfg *config.Config) (*Keeper, bool, error) {
	keeper := &Keeper{
		certificateFile: cfg.ResolvePath(cfg.TLS.CertificateFile),
		privateKeyFile:  cfg.ResolvePath(cfg.TLS.PrivateKeyFile),
		minimumVersion:  cfg.MinimumTLSVersion(),
	}

	var created bool

	_, err := os.Stat(keeper.certificateFile)
	if errors.Is(err, os.ErrNotExist) {
		if cfg.TLS.Mode != "self_signed" {
			return nil, false, fmt.Errorf("tls certificate %q does not exist", keeper.certificateFile)
		}

		err = keeper.generate(cfg.Server.Hostname)
		if err != nil {
			return nil, false, err
		}

		created = true
	} else if err != nil {
		return nil, false, err
	}

	_, err = keeper.load()
	if err != nil {
		return nil, false, err
	}

	return keeper, created, nil
}

// Config returns the TLS configuration for both submission listeners.
func (k *Keeper) Config() *tls.Config {
	return &tls.Config{
		MinVersion:     k.minimumVersion,
		GetCertificate: k.get,
		// AEAD only; the CBC suites Go still allows for TLS 1.2 cost points on every serious TLS scanner.
		CipherSuites: []uint16{
			tls.TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,
			tls.TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,
			tls.TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384,
			tls.TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,
			tls.TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305,
			tls.TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305,
		},
	}
}

func (k *Keeper) get(*tls.ClientHelloInfo) (*tls.Certificate, error) {
	k.mu.Lock()
	defer k.mu.Unlock()

	if time.Since(k.checked) < reloadInterval {
		return k.certificate, nil
	}

	k.checked = time.Now()

	stamp, err := k.modified()
	if err != nil || !stamp.After(k.stamp) {
		return k.certificate, nil
	}

	certificate, err := tls.LoadX509KeyPair(k.certificateFile, k.privateKeyFile)
	if err != nil {
		return k.certificate, nil
	}

	k.certificate = &certificate
	k.stamp = stamp

	return k.certificate, nil
}

func (k *Keeper) load() (*tls.Certificate, error) {
	certificate, err := tls.LoadX509KeyPair(k.certificateFile, k.privateKeyFile)
	if err != nil {
		return nil, err
	}

	stamp, err := k.modified()
	if err != nil {
		return nil, err
	}

	k.mu.Lock()
	k.certificate = &certificate
	k.stamp = stamp
	k.checked = time.Now()
	k.mu.Unlock()

	return &certificate, nil
}

func (k *Keeper) modified() (time.Time, error) {
	certificate, err := os.Stat(k.certificateFile)
	if err != nil {
		return time.Time{}, err
	}

	key, err := os.Stat(k.privateKeyFile)
	if err != nil {
		return time.Time{}, err
	}

	if key.ModTime().After(certificate.ModTime()) {
		return key.ModTime(), nil
	}

	return certificate.ModTime(), nil
}

func (k *Keeper) generate(hostname string) error {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return err
	}

	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return err
	}

	now := time.Now()

	template := x509.Certificate{
		SerialNumber:          serial,
		Subject:               pkix.Name{CommonName: hostname},
		DNSNames:              []string{hostname},
		NotBefore:             now.Add(-time.Hour),
		NotAfter:              now.AddDate(10, 0, 0),
		KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
	}

	body, err := x509.CreateCertificate(rand.Reader, &template, &template, &key.PublicKey, key)
	if err != nil {
		return err
	}

	encoded, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return err
	}

	err = disk.WriteExclusive(k.privateKeyFile, pem.EncodeToMemory(&pem.Block{
		Type:  "PRIVATE KEY",
		Bytes: encoded,
	}), 0600)

	if err != nil {
		return err
	}

	return disk.WriteExclusive(k.certificateFile, pem.EncodeToMemory(&pem.Block{
		Type:  "CERTIFICATE",
		Bytes: body,
	}), 0644)
}

package config

import (
	"bytes"
	"errors"
	"fmt"
	"net"
	"net/mail"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/coalaura/outboxd/internal/disk"
	"github.com/goccy/go-yaml"
)

type Config struct {
	dataMu *sync.RWMutex
	fileMu *sync.Mutex

	userLookup map[string]*User

	Server   Server   `yaml:"server"`
	TLS      TLS      `yaml:"tls"`
	DKIM     DKIM     `yaml:"dkim"`
	Delivery Delivery `yaml:"delivery"`
	DNS      DNS      `yaml:"dns"`
	Users    []User   `yaml:"users"`
}

type Server struct {
	Hostname                  string `yaml:"hostname"`
	Domain                    string `yaml:"domain"`
	MaxMessageBytes           int64  `yaml:"max_message_bytes"`
	MaxRecipients             int    `yaml:"max_recipients"`
	MaxMessagesPerHour        int    `yaml:"max_messages_per_hour"`
	MaxRecipientsPerHour      int    `yaml:"max_recipients_per_hour"`
	IncludeClientIPInReceived bool   `yaml:"include_client_ip_in_received"`
	ReadTimeout               string `yaml:"read_timeout"`
	WriteTimeout              string `yaml:"write_timeout"`
	DataDirectory             string `yaml:"data_directory"`
}

type TLS struct {
	Mode            string `yaml:"mode"`
	CertificateFile string `yaml:"certificate_file"`
	PrivateKeyFile  string `yaml:"private_key_file"`
	MinimumVersion  string `yaml:"minimum_version"`
}

type DKIM struct {
	Selector       string   `yaml:"selector"`
	PrivateKeyFile string   `yaml:"private_key_file"`
	Headers        []string `yaml:"headers"`
}

type Delivery struct {
	TLSMode               string `yaml:"tls_mode"`
	MaxAttempts           int    `yaml:"max_attempts"`
	MaximumLifetime       string `yaml:"maximum_lifetime"`
	InitialRetryDelay     string `yaml:"initial_retry_delay"`
	MaximumRetryDelay     string `yaml:"maximum_retry_delay"`
	DomainConcurrency     int    `yaml:"domain_concurrency"`
	GlobalConcurrency     int    `yaml:"global_concurrency"`
	ConnectionTimeout     string `yaml:"connection_timeout"`
	CommandTimeout        string `yaml:"command_timeout"`
	SubmissionTimeout     string `yaml:"submission_timeout"`
	RequireValidMXTLSCert bool   `yaml:"require_valid_mx_tls_certificate"`
}

type DNS struct {
	PublicIPv4 string `yaml:"public_ipv4"`
	PublicIPv6 string `yaml:"public_ipv6"`
	DMARC      string `yaml:"dmarc_policy"`
	ReportURI  string `yaml:"dmarc_report_uri"`
	OutputFile string `yaml:"output_file"`
}

type User struct {
	Username       string   `yaml:"username"`
	PasswordHash   string   `yaml:"password_hash"`
	AllowedSenders []string `yaml:"allowed_senders"`
	Enabled        bool     `yaml:"enabled"`
}

type durationEntry struct {
	name  string
	value string
}

const configPath = "config.yml"

// Default returns the default config
func Default() *Config {
	return &Config{
		Server: Server{
			Hostname:             "mail.example.invalid",
			Domain:               "example.invalid",
			MaxMessageBytes:      25 << 20,
			MaxRecipients:        100,
			MaxMessagesPerHour:   1000,
			MaxRecipientsPerHour: 10000,
			ReadTimeout:          "5m",
			WriteTimeout:         "5m",
			DataDirectory:        "./data",
		},
		TLS: TLS{
			Mode:            "self_signed",
			CertificateFile: "tls/server.crt",
			PrivateKeyFile:  "tls/server.key",
			MinimumVersion:  "1.2",
		},
		DKIM: DKIM{
			Selector:       "mail",
			PrivateKeyFile: "dkim/mail.key",
			Headers: []string{
				"From",
				"To",
				"Cc",
				"Subject",
				"Date",
				"Message-ID",
				"MIME-Version",
				"Content-Type",
				"Content-Transfer-Encoding",
				"Reply-To",
			},
		},
		Delivery: Delivery{
			TLSMode:               "opportunistic",
			MaxAttempts:           15,
			MaximumLifetime:       "120h",
			InitialRetryDelay:     "5m",
			MaximumRetryDelay:     "8h",
			DomainConcurrency:     2,
			GlobalConcurrency:     16,
			ConnectionTimeout:     "30s",
			CommandTimeout:        "5m",
			SubmissionTimeout:     "12m",
			RequireValidMXTLSCert: true,
		},
		DNS: DNS{
			DMARC:      "quarantine",
			OutputFile: "dns-records.txt",
		},
		Users: []User{
			{
				Username:     "example",
				PasswordHash: "$argon2id$v=19$m=19456,t=2,p=1$dmgLPdAEgsPfBznUbnX0jA$3jpi3X+lrcemQBB4cL5OwOcyaB3hFPBvwoNYpxbTxjs",
				AllowedSenders: []string{
					"example@example.invalid",
				},
				Enabled: false,
			},
		},
	}
}

// Load loads the config
func Load() (*Config, error) {
	cfg := Default()

	cfg.initializeRuntime()

	file, err := os.OpenFile(configPath, os.O_RDONLY, 0)
	if err != nil {
		return nil, err
	}

	defer file.Close()

	cfg.Users = nil

	err = yaml.NewDecoder(file, yaml.DisallowUnknownField()).Decode(cfg)
	if err != nil {
		return nil, err
	}

	err = cfg.Init()
	if err != nil {
		return nil, err
	}

	return cfg, nil
}

// Ensure loads the config or atomically creates it with secure defaults.
func Ensure() (*Config, bool, error) {
	cfg, err := Load()
	if err == nil {
		return cfg, false, nil
	}

	if !errors.Is(err, os.ErrNotExist) {
		return nil, false, err
	}

	cfg = Default()

	cfg.initializeRuntime()

	err = cfg.Init()
	if err != nil {
		return nil, false, err
	}

	err = cfg.storeExclusive()
	if err != nil {
		if errors.Is(err, os.ErrExist) {
			cfg, err = Load()

			return cfg, false, err
		}

		return nil, false, err
	}

	return cfg, true, nil
}

// Init validates the configuration and builds its runtime indexes.
func (cfg *Config) Init() error {
	cfg.initializeRuntime()

	err := cfg.Validate()
	if err != nil {
		return err
	}

	cfg.dataMu.Lock()
	defer cfg.dataMu.Unlock()

	cfg.userLookup = make(map[string]*User, len(cfg.Users))

	for i := range cfg.Users {
		user := &cfg.Users[i]

		username := canonicalUsername(user.Username)

		cfg.userLookup[username] = user
	}

	return nil
}

// User returns a snapshot of the configured user.
func (cfg *Config) User(username string) (User, bool) {
	cfg.dataMu.RLock()
	defer cfg.dataMu.RUnlock()

	user, ok := cfg.userLookup[canonicalUsername(username)]
	if !ok {
		return User{}, false
	}

	return User{
		Username:       user.Username,
		PasswordHash:   user.PasswordHash,
		Enabled:        user.Enabled,
		AllowedSenders: slices.Clone(user.AllowedSenders),
	}, true
}

// Validate validates all config options.
func (cfg *Config) Validate() error {
	err := validateDomain("server.hostname", cfg.Server.Hostname)
	if err != nil {
		return err
	}

	err = validateDomain("server.domain", cfg.Server.Domain)
	if err != nil {
		return err
	}

	if cfg.Server.MaxMessageBytes <= 0 {
		return errors.New("server.max_message_bytes must be positive")
	}

	if cfg.Server.MaxRecipients <= 0 {
		return errors.New("server.max_recipients must be positive")
	}

	if cfg.Server.MaxMessagesPerHour <= 0 {
		return errors.New("server.max_messages_per_hour must be positive")
	}

	if cfg.Server.MaxRecipientsPerHour <= 0 {
		return errors.New("server.max_recipients_per_hour must be positive")
	}

	if cfg.Server.DataDirectory == "" {
		return errors.New("server.data_directory must not be empty")
	}

	durations := []durationEntry{
		{"server.read_timeout", cfg.Server.ReadTimeout},
		{"server.write_timeout", cfg.Server.WriteTimeout},
		{"delivery.maximum_lifetime", cfg.Delivery.MaximumLifetime},
		{"delivery.initial_retry_delay", cfg.Delivery.InitialRetryDelay},
		{"delivery.maximum_retry_delay", cfg.Delivery.MaximumRetryDelay},
		{"delivery.connection_timeout", cfg.Delivery.ConnectionTimeout},
		{"delivery.command_timeout", cfg.Delivery.CommandTimeout},
		{"delivery.submission_timeout", cfg.Delivery.SubmissionTimeout},
	}

	for _, duration := range durations {
		err = validateDuration(duration.name, duration.value)
		if err != nil {
			return err
		}
	}

	switch cfg.TLS.Mode {
	case "self_signed", "files":
	default:
		return fmt.Errorf("unsupported tls.mode %q", cfg.TLS.Mode)
	}

	if cfg.TLS.CertificateFile == "" || cfg.TLS.PrivateKeyFile == "" {
		return errors.New("TLS certificate and private-key paths are required")
	}

	switch cfg.TLS.MinimumVersion {
	case "1.2", "1.3":
	default:
		return fmt.Errorf("tls.minimum_version must be 1.2 or 1.3, got %q", cfg.TLS.MinimumVersion)
	}

	err = validateDNSLabel("dkim.selector", cfg.DKIM.Selector)
	if err != nil {
		return err
	}

	if cfg.DKIM.PrivateKeyFile == "" {
		return errors.New("dkim.private_key_file must not be empty")
	}

	hasFromHeader := slices.ContainsFunc(cfg.DKIM.Headers, func(header string) bool {
		return strings.EqualFold(header, "From")
	})

	if !hasFromHeader {
		return errors.New("dkim.headers must contain From")
	}

	switch cfg.Delivery.TLSMode {
	case "opportunistic", "required":
	default:
		return fmt.Errorf("delivery.tls_mode must be opportunistic or required, got %q", cfg.Delivery.TLSMode)
	}

	if cfg.Delivery.MaxAttempts <= 0 {
		return errors.New("delivery.max_attempts must be positive")
	}

	if cfg.Delivery.DomainConcurrency <= 0 || cfg.Delivery.GlobalConcurrency <= 0 {
		return errors.New("delivery concurrency limits must be positive")
	}

	switch cfg.DNS.DMARC {
	case "none", "quarantine", "reject":
	default:
		return fmt.Errorf("invalid DMARC policy %q", cfg.DNS.DMARC)
	}

	if cfg.DNS.PublicIPv4 != "" && net.ParseIP(cfg.DNS.PublicIPv4).To4() == nil {
		return fmt.Errorf("invalid public IPv4 address %q", cfg.DNS.PublicIPv4)
	}

	if cfg.DNS.PublicIPv6 != "" {
		ip := net.ParseIP(cfg.DNS.PublicIPv6)
		if ip == nil || ip.To4() != nil {
			return fmt.Errorf("invalid public IPv6 address %q", cfg.DNS.PublicIPv6)
		}
	}

	usernames := make(map[string]struct{}, len(cfg.Users))

	for i := range cfg.Users {
		user := &cfg.Users[i]

		err = user.Validate()
		if err != nil {
			return fmt.Errorf("users[%d]: %w", i, err)
		}

		// Sender outside the DKIM domain can never produce an aligned DMARC pass.
		for _, sender := range user.AllowedSenders {
			domain := strings.ToLower(sender[strings.LastIndexByte(sender, '@')+1:])

			if domain != cfg.Server.Domain && !strings.HasSuffix(domain, "."+cfg.Server.Domain) {
				return fmt.Errorf("users[%d]: sender %q is outside server.domain %q; DKIM signs with d=%s so this mail cannot pass DMARC", i, sender, cfg.Server.Domain, cfg.Server.Domain)
			}
		}

		username := canonicalUsername(user.Username)
		if _, exists := usernames[username]; exists {
			return fmt.Errorf("duplicate username %q", user.Username)
		}

		usernames[username] = struct{}{}
	}

	return nil
}

// Validate normalizes a single user in place and reports why it is unusable.
func (u *User) Validate() error {
	u.Username = strings.TrimSpace(u.Username)

	if u.Username == "" {
		return errors.New("username must not be empty")
	}

	if strings.ContainsAny(u.Username, "\x00\r\n") {
		return fmt.Errorf("invalid username %q", u.Username)
	}

	if !strings.HasPrefix(u.PasswordHash, "$argon2id$") {
		return fmt.Errorf("user %q must have an Argon2id password hash", u.Username)
	}

	if len(u.AllowedSenders) == 0 {
		return fmt.Errorf("user %q has no allowed senders", u.Username)
	}

	senders := make(map[string]struct{}, len(u.AllowedSenders))

	for i, sender := range u.AllowedSenders {
		sender = strings.TrimSpace(sender)

		address, err := mail.ParseAddress(sender)
		if err != nil || address.Address != sender {
			return fmt.Errorf("user %q has invalid sender %q", u.Username, sender)
		}

		canonicalSender := strings.ToLower(address.Address)
		if _, exists := senders[canonicalSender]; exists {
			return fmt.Errorf("user %q has duplicate sender %q", u.Username, sender)
		}

		senders[canonicalSender] = struct{}{}
		u.AllowedSenders[i] = canonicalSender
	}

	return nil
}

// IsReady reports configuration options that must be corrected before serving.
func (cfg *Config) IsReady() error {
	var problems []error

	if strings.HasSuffix(cfg.Server.Domain, ".invalid") {
		problems = append(problems, errors.New("replace server.domain with the sending domain"))
	}

	if strings.HasSuffix(cfg.Server.Hostname, ".invalid") {
		problems = append(problems, errors.New("replace server.hostname with the public SMTP hostname"))
	}

	if cfg.DNS.PublicIPv4 == "" && cfg.DNS.PublicIPv6 == "" {
		problems = append(problems, errors.New("configure at least one public sending IP"))
	}

	if len(cfg.Users) == 0 {
		problems = append(problems, errors.New("configure at least one SMTP user"))
	}

	return errors.Join(problems...)
}

// Warnings reports non-fatal deliverability problems.
func (cfg *Config) Warnings() []string {
	var warnings []string

	if cfg.TLS.Mode == "self_signed" {
		warnings = append(warnings, "tls.mode is self_signed; submission clients must trust the generated certificate")
	}

	if cfg.DNS.DMARC == "none" {
		warnings = append(warnings, `dmarc_policy is "none"; move to quarantine or reject once alignment is verified`)
	}

	if cfg.DNS.ReportURI == "" {
		warnings = append(warnings, "dns.dmarc_report_uri is empty; you will receive no DMARC reports and have no view of failures")
	}

	if cfg.Delivery.TLSMode == "opportunistic" {
		warnings = append(warnings, "delivery.tls_mode is opportunistic; destinations without STARTTLS receive plaintext")
	}

	return warnings
}

// ResolvePath resolves a path relative to the configured data directory.
func (cfg Config) ResolvePath(path string) string {
	if filepath.IsAbs(path) {
		return path
	}

	return filepath.Join(cfg.Server.DataDirectory, path)
}

func (cfg *Config) initializeRuntime() {
	if cfg.dataMu == nil {
		cfg.dataMu = new(sync.RWMutex)
	}

	if cfg.fileMu == nil {
		cfg.fileMu = new(sync.Mutex)
	}
}

func (cfg *Config) storeExclusive() error {
	body, err := cfg.marshal()
	if err != nil {
		return err
	}

	cfg.fileMu.Lock()
	defer cfg.fileMu.Unlock()

	return disk.WriteExclusive(configPath, body, 0600)
}

func (cfg *Config) marshal() ([]byte, error) {
	var buffer bytes.Buffer

	comments := yaml.CommentMap{
		"$.server":                               {yaml.HeadComment(" SMTP submission server")},
		"$.server.hostname":                      {yaml.HeadComment(" public SMTP hostname used for EHLO, TLS, MX, and reverse DNS")},
		"$.server.domain":                        {yaml.HeadComment(" sending domain used for DKIM, SPF, and DMARC")},
		"$.server.max_message_bytes":             {yaml.HeadComment(" maximum accepted message size in bytes")},
		"$.server.max_recipients":                {yaml.HeadComment(" maximum recipients accepted for one message")},
		"$.server.max_messages_per_hour":         {yaml.HeadComment(" per-user token-bucket limit for accepted messages")},
		"$.server.max_recipients_per_hour":       {yaml.HeadComment(" per-user token-bucket limit for accepted recipients")},
		"$.server.include_client_ip_in_received": {yaml.HeadComment(" include the submitting client's IP address in Received headers")},
		"$.server.read_timeout":                  {yaml.HeadComment(" maximum time spent waiting for an SMTP command")},
		"$.server.write_timeout":                 {yaml.HeadComment(" maximum time spent writing an SMTP response")},
		"$.server.data_directory":                {yaml.HeadComment(" generated keys, certificates, DNS instructions and queue data")},

		"$.tls":                  {yaml.HeadComment("\n# TLS used by the submission listeners")},
		"$.tls.mode":             {yaml.HeadComment(` "self_signed" generates a development certificate; use "files" in production`)},
		"$.tls.certificate_file": {yaml.HeadComment(" certificate chain; relative paths are resolved below data_directory")},
		"$.tls.private_key_file": {yaml.HeadComment(" TLS private key; relative paths are resolved below data_directory")},
		"$.tls.minimum_version":  {yaml.HeadComment(` minimum accepted TLS version: "1.2" or "1.3"`)},

		"$.dkim":                  {yaml.HeadComment("\n# DKIM signing configuration")},
		"$.dkim.selector":         {yaml.HeadComment(" DNS selector placed before _domainkey")},
		"$.dkim.private_key_file": {yaml.HeadComment(" automatically generated when absent")},
		"$.dkim.headers":          {yaml.HeadComment(" message headers included in the DKIM signature; From is mandatory")},

		"$.delivery":                                  {yaml.HeadComment("\n# outbound SMTP delivery and retry policy")},
		"$.delivery.tls_mode":                         {yaml.HeadComment(` destination TLS policy: "opportunistic" or "required"`)},
		"$.delivery.max_attempts":                     {yaml.HeadComment(" maximum delivery attempts before moving a message to dead-letter state")},
		"$.delivery.maximum_lifetime":                 {yaml.HeadComment(" absolute time a message may remain queued before dead-lettering")},
		"$.delivery.initial_retry_delay":              {yaml.HeadComment(" delay after the first temporary delivery failure")},
		"$.delivery.maximum_retry_delay":              {yaml.HeadComment(" upper bound for exponential retry delays")},
		"$.delivery.domain_concurrency":               {yaml.HeadComment(" maximum simultaneous deliveries to one recipient domain")},
		"$.delivery.global_concurrency":               {yaml.HeadComment(" maximum simultaneous outbound deliveries")},
		"$.delivery.connection_timeout":               {yaml.HeadComment(" timeout while connecting to a destination MX")},
		"$.delivery.command_timeout":                  {yaml.HeadComment(" timeout while waiting for normal SMTP responses")},
		"$.delivery.submission_timeout":               {yaml.HeadComment(" timeout while waiting for the response after message data")},
		"$.delivery.require_valid_mx_tls_certificate": {yaml.HeadComment(" verify destination certificates whenever TLS is negotiated")},

		"$.dns":                  {yaml.HeadComment("\n# values used to generate dns-records.txt")},
		"$.dns.public_ipv4":      {yaml.HeadComment(" static public IPv4 address used for outbound delivery")},
		"$.dns.public_ipv6":      {yaml.HeadComment(" static public IPv6 address; omit until forward and reverse DNS are ready")},
		"$.dns.dmarc_policy":     {yaml.HeadComment(` "quarantine" is a safe default; move to "reject" once reports look clean`)},
		"$.dns.dmarc_report_uri": {yaml.HeadComment(" optional external aggregate-report URI, for example mailto:dmarc@example.com")},
		"$.dns.output_file":      {yaml.HeadComment(" generated DNS instructions; relative paths are below data_directory")},

		"$.users": {yaml.HeadComment("\n# SMTP users; password_hash must contain an Argon2id hash, never plaintext")},
	}

	cfg.dataMu.RLock()
	err := yaml.NewEncoder(&buffer, yaml.WithComment(comments), yaml.Indent(2)).Encode(cfg)
	cfg.dataMu.RUnlock()

	if err != nil {
		return nil, err
	}

	body := bytes.ReplaceAll(buffer.Bytes(), []byte("\n#\n"), []byte("\n\n"))

	return body, nil
}

func canonicalUsername(username string) string {
	return strings.ToLower(strings.TrimSpace(username))
}

func validateDuration(name, value string) error {
	duration, err := time.ParseDuration(value)
	if err != nil {
		return err
	}

	if duration <= 0 {
		return fmt.Errorf("%s must be positive", name)
	}

	return nil
}

func validateDomain(name, domain string) error {
	if len(domain) > 253 || strings.HasPrefix(domain, ".") || strings.HasSuffix(domain, ".") {
		return fmt.Errorf("invalid %s %q", name, domain)
	}

	for label := range strings.SplitSeq(domain, ".") {
		err := validateDNSLabel(name, label)
		if err != nil {
			return err
		}
	}

	return nil
}

func validateDNSLabel(name, label string) error {
	if label == "" || len(label) > 63 || label[0] == '-' || label[len(label)-1] == '-' {
		return fmt.Errorf("invalid %s %q", name, label)
	}

	for _, char := range label {
		if char != '-' && (char < 'a' || char > 'z') && (char < 'A' || char > 'Z') && (char < '0' || char > '9') {
			return fmt.Errorf("invalid %s %q", name, label)
		}
	}

	return nil
}

package config

import (
	"crypto/tls"
	"strings"
	"time"
)

// MinimumTLSVersion returns the configured floor for the submission listeners.
func (cfg *Config) MinimumTLSVersion() uint16 {
	if cfg.TLS.MinimumVersion == "1.3" {
		return tls.VersionTLS13
	}

	return tls.VersionTLS12
}

// Allows reports whether the user may send as the given address.
func (u User) Allows(address string) bool {
	address = strings.ToLower(strings.TrimSpace(address))

	at := strings.LastIndexByte(address, '@')
	if at <= 0 || at == len(address)-1 {
		return false
	}

	domain := address[at+1:]

	for _, sender := range u.AllowedSenders {
		if sender == address {
			return true
		}

		if strings.HasPrefix(sender, "*@") && sender[2:] == domain {
			return true
		}
	}

	return false
}

// Duration parses a duration that Validate already accepted.
func Duration(value string) time.Duration {
	duration, _ := time.ParseDuration(value)

	return duration
}

package deliver

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"net"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/queue"
	"github.com/emersion/go-smtp"
)

const lifetimeDetail = "maximum queue lifetime exceeded"

// Logger receives operational messages.
type Logger interface {
	Printf(format string, values ...any)
	Println(values ...any)
}

var (
	errNullMX              = errors.New("domain does not accept mail (null MX)")
	errNoSuchDomain        = errors.New("recipient domain does not exist")
	errSMTPUTF8Unsupported = errors.New("destination does not support SMTPUTF8")
)

// Deliverer drains the queue towards the destination MX servers.
type Deliverer struct {
	cfg   *config.Config
	queue *queue.Queue
	log   Logger

	resolver *net.Resolver
	dialer   *net.Dialer
	network  string

	global  chan struct{}
	domains *domainLimiter

	command    time.Duration
	submission time.Duration
	lifetime   time.Duration
	initial    time.Duration
	maximum    time.Duration
}

// New builds the outbound delivery worker pool.
func New(cfg *config.Config, spool *queue.Queue, log Logger) *Deliverer {
	dialer := &net.Dialer{Timeout: config.Duration(cfg.Delivery.ConnectionTimeout)}
	network := "tcp"

	if cfg.DNS.PublicIPv6 == "" {
		network = "tcp4"

		ip := net.ParseIP(cfg.DNS.PublicIPv4)
		if ip != nil {
			dialer.LocalAddr = &net.TCPAddr{IP: ip}
		}
	}

	return &Deliverer{
		cfg:   cfg,
		queue: spool,
		log:   log,

		resolver: net.DefaultResolver,
		dialer:   dialer,
		network:  network,

		global:  make(chan struct{}, cfg.Delivery.GlobalConcurrency),
		domains: newDomainLimiter(cfg.Delivery.DomainConcurrency),

		command:    config.Duration(cfg.Delivery.CommandTimeout),
		submission: config.Duration(cfg.Delivery.SubmissionTimeout),
		lifetime:   config.Duration(cfg.Delivery.MaximumLifetime),
		initial:    config.Duration(cfg.Delivery.InitialRetryDelay),
		maximum:    config.Duration(cfg.Delivery.MaximumRetryDelay),
	}
}

// Run delivers queued messages until ctx is cancelled.
func (d *Deliverer) Run(ctx context.Context) error {
	d.log.Printf("Delivery started with %d queued message(s)\n", d.queue.Len())

	var wg sync.WaitGroup

	defer wg.Wait()

	for {
		envelope, err := d.queue.Next(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return nil
			}

			return err
		}

		select {
		case d.global <- struct{}{}:
		case <-ctx.Done():
			return nil
		}

		wg.Go(func() {
			defer func() {
				<-d.global
			}()

			d.attempt(ctx, envelope)
		})
	}
}

func (d *Deliverer) attempt(ctx context.Context, envelope *queue.Envelope) {
	if ctx.Err() != nil {
		return
	}

	if d.expire(envelope) {
		return
	}

	envelope.Attempts++
	envelope.LastError = ""

	groups := make(map[string][]int, len(envelope.Recipients))

	for i := range envelope.Recipients {
		recipient := &envelope.Recipients[i]

		if recipient.Status != queue.StatusPending {
			continue
		}

		groups[recipient.Domain] = append(groups[recipient.Domain], i)
	}

	for domain, indexes := range groups {
		if ctx.Err() != nil {
			break
		}

		err := d.domains.acquire(ctx, domain)
		if err != nil {
			break
		}

		err = d.domain(ctx, envelope, domain, indexes)

		d.domains.release(domain)

		if err != nil {
			envelope.LastError = fmt.Sprintf("%s: %s", domain, err)
		}
	}

	switch {
	case envelope.Pending() == 0:
		d.finish(envelope)
	case envelope.Attempts >= d.cfg.Delivery.MaxAttempts:
		for i := range envelope.Recipients {
			recipient := &envelope.Recipients[i]

			if recipient.Status == queue.StatusPending {
				recipient.Status = queue.StatusFailed
				recipient.Detail = "delivery attempts exhausted"
			}
		}

		d.log.Printf("giving up on %s after %d attempts: %s\n", envelope.ID, envelope.Attempts, envelope.LastError)

		err := d.queue.Bury(envelope)
		if err != nil {
			d.log.Printf("failed to bury %s: %v\n", envelope.ID, err)
		}
	default:
		envelope.NextAttempt = time.Now().Add(d.backoff(envelope.Attempts))

		deadline := envelope.Created.Add(d.lifetime)
		if deadline.Before(envelope.NextAttempt) {
			envelope.NextAttempt = deadline
		}

		d.log.Printf("retrying %s in %s: %s\n", envelope.ID, time.Until(envelope.NextAttempt).Round(time.Second), envelope.LastError)

		err := d.queue.Retry(envelope)
		if err != nil {
			d.log.Printf("failed to reschedule %s: %v\n", envelope.ID, err)
		}
	}
}

func (d *Deliverer) expire(envelope *queue.Envelope) bool {
	if time.Now().Before(envelope.Created.Add(d.lifetime)) {
		return false
	}

	for i := range envelope.Recipients {
		recipient := &envelope.Recipients[i]

		if recipient.Status == queue.StatusPending {
			recipient.Status = queue.StatusFailed
			recipient.Detail = lifetimeDetail
		}
	}

	envelope.LastError = lifetimeDetail

	d.log.Printf("expiring %s after %s\n", envelope.ID, d.lifetime)

	err := d.queue.Bury(envelope)
	if err != nil {
		d.log.Printf("failed to bury expired message %s: %v\n", envelope.ID, err)
	}

	return true
}

func (d *Deliverer) finish(envelope *queue.Envelope) {
	var delivered int

	for i := range envelope.Recipients {
		if envelope.Recipients[i].Status == queue.StatusSent {
			delivered++
		}
	}

	d.log.Printf("completed %s: %d delivered, %d failed\n", envelope.ID, delivered, len(envelope.Recipients)-delivered)

	err := d.queue.Finish(envelope)
	if err != nil {
		d.log.Printf("failed to remove %s: %v\n", envelope.ID, err)
	}
}

func (d *Deliverer) domain(ctx context.Context, envelope *queue.Envelope, domain string, indexes []int) error {
	hosts, err := d.hosts(ctx, domain)
	if err != nil {
		if errors.Is(err, errNullMX) || errors.Is(err, errNoSuchDomain) {
			d.reject(envelope, indexes, err.Error())

			return nil
		}

		return err
	}

	var (
		last               error
		allUTF8Unsupported = len(hosts) > 0
	)

	for _, host := range hosts {
		if ctx.Err() != nil {
			return ctx.Err()
		}

		done, err := d.send(ctx, envelope, host, indexes)
		if done {
			return nil
		}

		if errors.Is(err, errSMTPUTF8Unsupported) {
			if last == nil {
				last = err
			}

			continue
		}

		allUTF8Unsupported = false
		last = err
	}

	if allUTF8Unsupported && last != nil {
		d.reject(envelope, indexes, errSMTPUTF8Unsupported.Error())

		return nil
	}

	if last == nil {
		last = errors.New("no usable MX host")
	}

	return last
}

func (d *Deliverer) send(ctx context.Context, envelope *queue.Envelope, host string, indexes []int) (bool, error) {
	client, err := d.connect(ctx, host)
	if err != nil {
		return false, err
	}

	defer client.Close()

	client.CommandTimeout = d.command
	client.SubmissionTimeout = d.submission

	if envelope.SMTPUTF8 {
		supported, _ := client.Extension("SMTPUTF8")
		if !supported {
			client.Quit()

			return false, errSMTPUTF8Unsupported
		}
	}

	err = client.Mail(envelope.Sender, &smtp.MailOptions{
		Size: envelope.Size,
		UTF8: envelope.SMTPUTF8,
	})

	if err != nil {
		if permanent(err) {
			d.reject(envelope, indexes, describe(err))

			return true, nil
		}

		return false, err
	}

	accepted := make([]int, 0, len(indexes))

	for _, index := range indexes {
		recipient := &envelope.Recipients[index]

		// An earlier MX in this attempt already rejected the address for good.
		if recipient.Status != queue.StatusPending {
			continue
		}

		err = client.Rcpt(recipient.Address, nil)
		if err == nil {
			accepted = append(accepted, index)

			continue
		}

		if permanent(err) {
			recipient.Status = queue.StatusFailed
			recipient.Detail = describe(err)

			continue
		}

		recipient.Detail = describe(err)
	}

	if len(accepted) == 0 {
		client.Quit()

		return true, nil
	}

	reader, err := d.queue.Reader(envelope.ID)
	if err != nil {
		return false, err
	}

	defer reader.Close()

	data, err := client.Data()
	if err != nil {
		if permanent(err) {
			d.reject(envelope, accepted, describe(err))

			return true, nil
		}

		return false, err
	}

	_, err = io.Copy(data, reader)
	if err != nil {
		return false, err
	}

	response, err := data.CloseWithResponse()
	if err != nil {
		if permanent(err) {
			d.reject(envelope, accepted, describe(err))

			return true, nil
		}

		return false, err
	}

	for _, index := range accepted {
		recipient := &envelope.Recipients[index]

		recipient.Status = queue.StatusSent
		recipient.Detail = fmt.Sprintf("%s: %s", host, strings.TrimSpace(response.StatusText))
	}

	client.Quit()

	return true, nil
}

func (d *Deliverer) connect(ctx context.Context, host string) (*smtp.Client, error) {
	required := d.cfg.Delivery.TLSMode == "required"
	requireValidCertificate := d.cfg.Delivery.RequireValidMXTLSCert

	client, verifiedErr := d.dial(ctx, host, true)
	if verifiedErr == nil {
		return client, nil
	}

	var unverifiedErr error

	if requireValidCertificate {
		if required {
			return nil, verifiedErr
		}
	} else {
		client, unverifiedErr = d.dial(ctx, host, false)
		if unverifiedErr == nil {
			return client, nil
		}

		if required {
			return nil, errors.Join(verifiedErr, unverifiedErr)
		}
	}

	conn, plainErr := d.dialer.DialContext(ctx, "tcp", net.JoinHostPort(host, "25"))
	if plainErr != nil {
		return nil, errors.Join(verifiedErr, unverifiedErr, plainErr)
	}

	client = smtp.NewClient(conn)

	helloErr := client.Hello(d.cfg.Server.Hostname)
	if helloErr != nil {
		client.Close()

		return nil, errors.Join(verifiedErr, unverifiedErr, helloErr)
	}

	return client, nil
}

func (d *Deliverer) dial(ctx context.Context, host string, verify bool) (*smtp.Client, error) {
	conn, err := d.dialer.DialContext(ctx, d.network, net.JoinHostPort(host, "25"))
	if err != nil {
		return nil, err
	}

	client, err := smtp.NewClientStartTLS(conn, &tls.Config{
		ServerName: host,
		MinVersion: tls.VersionTLS12,
		// Deliberate: opportunistic TLS to an unknown MX is still better than plaintext,
		// most MX certificates are not publicly trusted.
		InsecureSkipVerify: !verify,
	})

	if err != nil {
		conn.Close()

		return nil, err
	}

	err = client.Hello(d.cfg.Server.Hostname)
	if err != nil {
		client.Close()

		return nil, err
	}

	return client, nil
}

func (d *Deliverer) hosts(ctx context.Context, domain string) ([]string, error) {
	records, err := d.resolver.LookupMX(ctx, domain)
	if err != nil {
		dnsErr, ok := errors.AsType[*net.DNSError](err)
		if !ok || !dnsErr.IsNotFound {
			return nil, err
		}

		_, err = d.resolver.LookupNetIP(ctx, "ip", domain)
		if err != nil {
			if dnsErr, ok := errors.AsType[*net.DNSError](err); ok && dnsErr.IsNotFound {
				return nil, errNoSuchDomain
			}

			return nil, err
		}

		return []string{domain}, nil
	}

	if len(records) == 0 {
		return []string{domain}, nil
	}

	if len(records) == 1 && records[0].Host == "." {
		return nil, errNullMX
	}

	rand.Shuffle(len(records), func(i, j int) {
		records[i], records[j] = records[j], records[i]
	})

	slices.SortStableFunc(records, func(a, b *net.MX) int {
		return int(a.Pref) - int(b.Pref)
	})

	hosts := make([]string, 0, len(records))

	for _, record := range records {
		host := strings.TrimSuffix(record.Host, ".")

		if host != "" {
			hosts = append(hosts, host)
		}
	}

	return hosts, nil
}

func (d *Deliverer) reject(envelope *queue.Envelope, indexes []int, detail string) {
	for _, index := range indexes {
		recipient := &envelope.Recipients[index]

		recipient.Status = queue.StatusFailed
		recipient.Detail = detail
	}
}

func (d *Deliverer) backoff(attempts int) time.Duration {
	delay := d.initial

	for range attempts - 1 {
		delay *= 2

		if delay >= d.maximum {
			delay = d.maximum

			break
		}
	}

	spread := int64(delay / 5)
	if spread <= 0 {
		return delay
	}

	return delay + time.Duration(rand.Int64N(spread)) - delay/10
}

func permanent(err error) bool {
	if smtpErr, ok := errors.AsType[*smtp.SMTPError](err); ok {
		return smtpErr.Code >= 500
	}

	return false
}

func describe(err error) string {
	if smtpErr, ok := errors.AsType[*smtp.SMTPError](err); ok {
		return fmt.Sprintf("%d %s", smtpErr.Code, strings.TrimSpace(smtpErr.Message))
	}

	return err.Error()
}

package deliver

import (
	"context"
	"sync"
)

type slot struct {
	tokens  chan struct{}
	holders int
}

type domainLimiter struct {
	limit int

	mu    sync.Mutex
	slots map[string]*slot
}

func newDomainLimiter(limit int) *domainLimiter {
	return &domainLimiter{
		limit: limit,
		slots: make(map[string]*slot),
	}
}

func (l *domainLimiter) acquire(ctx context.Context, domain string) error {
	l.mu.Lock()

	entry, ok := l.slots[domain]
	if !ok {
		entry = &slot{tokens: make(chan struct{}, l.limit)}

		l.slots[domain] = entry
	}

	entry.holders++
	l.mu.Unlock()

	select {
	case entry.tokens <- struct{}{}:
		return nil
	case <-ctx.Done():
		l.drop(domain)

		return ctx.Err()
	}
}

func (l *domainLimiter) release(domain string) {
	l.mu.Lock()
	entry, ok := l.slots[domain]
	l.mu.Unlock()

	if !ok {
		return
	}

	<-entry.tokens

	l.drop(domain)
}

func (l *domainLimiter) drop(domain string) {
	l.mu.Lock()
	defer l.mu.Unlock()

	entry, ok := l.slots[domain]
	if !ok {
		return
	}

	entry.holders--

	if entry.holders <= 0 {
		delete(l.slots, domain)
	}
}

package disk

import (
	"os"
	"path/filepath"
)

// Mkdir creates a directory and its parents with owner-only permissions.
func Mkdir(path string) error {
	return os.MkdirAll(path, 0700)
}

// Temp creates a temporary file inside the target directory of path.
func Temp(path string) (*os.File, error) {
	directory := filepath.Dir(path)

	err := Mkdir(directory)
	if err != nil {
		return nil, err
	}

	return os.CreateTemp(directory, "."+filepath.Base(path)+".tmp-*")
}

// Commit flushes, closes and atomically moves file into place.
func Commit(file *os.File, path string, mode os.FileMode) error {
	temp := file.Name()

	err := commit(file, temp, path, mode)
	if err != nil {
		file.Close()
		os.Remove(temp)

		return err
	}

	return nil
}

// Write atomically replaces the file at path.
func Write(path string, body []byte, mode os.FileMode) error {
	file, err := Temp(path)
	if err != nil {
		return err
	}

	_, err = file.Write(body)
	if err != nil {
		file.Close()

		os.Remove(file.Name())

		return err
	}

	return Commit(file, path, mode)
}

// WriteExclusive writes path, failing with os.ErrExist if it already exists.
func WriteExclusive(path string, body []byte, mode os.FileMode) error {
	err := Mkdir(filepath.Dir(path))
	if err != nil {
		return err
	}

	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return err
	}

	remove := true

	defer func() {
		if remove {
			os.Remove(path)
		}
	}()

	_, err = file.Write(body)
	if err != nil {
		file.Close()

		return err
	}

	err = file.Sync()
	if err != nil {
		file.Close()

		return err
	}

	err = file.Close()
	if err != nil {
		return err
	}

	remove = false

	return Sync(filepath.Dir(path))
}

func commit(file *os.File, temp, path string, mode os.FileMode) error {
	err := file.Chmod(mode)
	if err != nil {
		return err
	}

	err = file.Sync()
	if err != nil {
		return err
	}

	err = file.Close()
	if err != nil {
		return err
	}

	err = os.Rename(temp, path)
	if err != nil {
		return err
	}

	return Sync(filepath.Dir(path))
}

//go:build !windows

package disk

import (
	"errors"
	"os"
	"syscall"
)

// Sync flushes a directory entry so renames survive a crash.
func Sync(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}

	defer directory.Close()

	err = directory.Sync()

	if errors.Is(err, syscall.EINVAL) || errors.Is(err, syscall.ENOTSUP) {
		return nil
	}

	return err
}

