package disk

// Sync is a no-op on Windows. Directory handles cannot be opened for writing.
func Sync(_ string) error {
	return nil
}

package message

import (
	"bytes"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"mime"
	"net/mail"
	"strconv"
	"strings"
	"time"
)

const (
	maxLineLength  = 998
	maxTraceLength = 128
)

var (
	errEmpty     = errors.New("message is empty")
	errMalformed = errors.New("message header is malformed")
	errNoFrom    = errors.New("message has no From header")
	errManyFrom  = errors.New("message has more than one From header")
	errBinary    = errors.New("message contains a NUL byte")
	errLongLine  = fmt.Errorf("message contains a line longer than %d octets; use quoted-printable or base64", maxLineLength)

	crlf = []byte("\r\n")
)

// Options carries the trace information added to the message.
type Options struct {
	Hostname string
	Helo     string
	Remote   string
	TLS      string
}

// Message is a submission that is ready to be signed and queued.
type Message struct {
	Data []byte
	From string
	ID   string
}

type field struct {
	name  string
	value []byte
}

var parser = mail.AddressParser{WordDecoder: new(mime.WordDecoder)}

func (f field) text() string {
	_, body, _ := bytes.Cut(f.value, []byte(":"))

	// Unfolding only has to drop the CRLF; the folding whitespace stays.
	return string(bytes.TrimSpace(bytes.ReplaceAll(body, crlf, nil)))
}

// Prepare normalizes a submitted message and adds the headers a receiving MTA
// expects to see.
func Prepare(r io.Reader, opts Options) (*Message, error) {
	raw, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}

	if len(raw) == 0 {
		return nil, errEmpty
	}

	data, err := normalize(raw)
	if err != nil {
		return nil, err
	}

	header, body := split(data)

	fields, err := scan(header)
	if err != nil {
		return nil, err
	}

	present := make(map[string]int, len(fields))

	for _, field := range fields {
		present[field.name]++
	}

	switch present["from"] {
	case 1:
	case 0:
		return nil, errNoFrom
	default:
		return nil, errManyFrom
	}

	var from string

	for _, field := range fields {
		if field.name != "from" {
			continue
		}

		address, err := parser.Parse(field.text())
		if err != nil {
			return nil, fmt.Errorf("invalid From header: %w", err)
		}

		from = address.Address
	}

	identifierDomain := opts.Hostname

	if at := strings.LastIndexByte(from, '@'); at >= 0 && at < len(from)-1 {
		identifierDomain = from[at+1:]
	}

	identifier := messageID(identifierDomain)

	var out bytes.Buffer

	out.Grow(len(data) + 512)

	fmt.Fprintf(&out, "Received: from %s", traceValue(opts.Helo))

	if opts.Remote != "" {
		fmt.Fprintf(&out, " (%s)", traceValue(opts.Remote))
	}

	fmt.Fprintf(
		&out,
		"\r\n\tby %s with %s id %s;\r\n\t%s\r\n",
		opts.Hostname, protocol(opts.TLS), strings.Trim(identifier, "<>"),
		time.Now().Format(time.RFC1123Z),
	)

	if present["date"] == 0 {
		fmt.Fprintf(&out, "Date: %s\r\n", time.Now().Format(time.RFC1123Z))
	}

	if present["message-id"] == 0 {
		fmt.Fprintf(&out, "Message-ID: %s\r\n", identifier)
	}

	if present["to"] == 0 && present["cc"] == 0 {
		out.WriteString("To: undisclosed-recipients:;\r\n")
	}

	eightBit := !ascii(body)

	if present["content-type"] == 0 && eightBit {
		out.WriteString("Content-Type: text/plain; charset=utf-8\r\n")

		present["content-type"]++
	}

	if present["content-transfer-encoding"] == 0 && eightBit {
		out.WriteString("Content-Transfer-Encoding: 8bit\r\n")
	}

	if present["mime-version"] == 0 && present["content-type"] > 0 {
		out.WriteString("MIME-Version: 1.0\r\n")
	}

	for _, field := range fields {
		// Bcc must never leave the submission server, and Return-Path is set by
		// the receiving MTA from the envelope.
		if field.name == "bcc" || field.name == "return-path" {
			continue
		}

		out.Write(field.value)
	}

	out.Write(crlf)
	out.Write(body)

	return &Message{
		Data: out.Bytes(),
		From: from,
		ID:   identifier,
	}, nil
}

func normalize(raw []byte) ([]byte, error) {
	if bytes.IndexByte(raw, 0) >= 0 {
		return nil, errBinary
	}

	out := make([]byte, 0, len(raw)+len(raw)/16)

	length := 0

	for i := 0; i < len(raw); i++ {
		switch raw[i] {
		case '\r':
			if i+1 < len(raw) && raw[i+1] == '\n' {
				i++
			}

			out = append(out, crlf...)
			length = 0
		case '\n':
			out = append(out, crlf...)
			length = 0
		default:
			out = append(out, raw[i])

			length++
			if length > maxLineLength {
				return nil, errLongLine
			}
		}
	}

	if !bytes.HasSuffix(out, crlf) {
		out = append(out, crlf...)
	}

	return out, nil
}

func split(data []byte) (header, body []byte) {
	separator := bytes.Index(data, []byte("\r\n\r\n"))
	if separator < 0 {
		return data, nil
	}

	return data[:separator+2], data[separator+4:]
}

func scan(header []byte) ([]field, error) {
	var (
		fields []field
		start  int
	)

	for offset := 0; offset < len(header); {
		end := bytes.Index(header[offset:], crlf)
		if end < 0 {
			return nil, errMalformed
		}

		end += offset + 2
		line := header[offset:end]

		if line[0] == ' ' || line[0] == '\t' {
			if len(fields) == 0 {
				return nil, errMalformed
			}

			fields[len(fields)-1].value = header[start:end]
			offset = end

			continue
		}

		colon := bytes.IndexByte(line, ':')
		if colon <= 0 {
			return nil, errMalformed
		}

		name := bytes.TrimRight(line[:colon], " \t")

		for _, char := range name {
			if char < 33 || char > 126 {
				return nil, errMalformed
			}
		}

		start = offset

		fields = append(fields, field{
			name:  strings.ToLower(string(name)),
			value: line,
		})

		offset = end
	}

	return fields, nil
}

func traceValue(value string) string {
	var builder strings.Builder

	builder.Grow(min(len(value), maxTraceLength))

	for _, char := range value {
		if builder.Len() >= maxTraceLength {
			break
		}

		if char < 33 || char > 126 || char == '(' || char == ')' || char == '\\' {
			continue
		}

		builder.WriteRune(char)
	}

	if builder.Len() == 0 {
		return "unknown"
	}

	return builder.String()
}

func messageID(hostname string) string {
	return fmt.Sprintf(
		"<%s.%s@%s>",
		strconv.FormatInt(time.Now().Unix(), 36),
		strings.ToLower(rand.Text()),
		hostname,
	)
}

func comment(value string) string {
	const limit = 128

	value = strings.Map(func(char rune) rune {
		if char < 33 || char > 126 || char == '(' || char == ')' || char == '\\' {
			return -1
		}

		return char
	}, value)

	if value == "" {
		return "unknown"
	}

	if len(value) > limit {
		return value[:limit]
	}

	return value
}

func protocol(state string) string {
	if state == "" {
		return "ESMTPA"
	}

	return "ESMTPSA"
}

func ascii(body []byte) bool {
	for _, char := range body {
		if char > 127 {
			return false
		}
	}

	return true
}

package passwd

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"strconv"
	"strings"

	"golang.org/x/crypto/argon2"
)

const (
	hashMemory  = 19 * 1024
	hashTime    = 2
	hashThreads = 1

	saltLength = 16
	keyLength  = 32
)

var ErrInvalidHash = errors.New("malformed argon2id hash")

var encoding = base64.RawStdEncoding

// Hash derives an Argon2id hash in PHC string format.
func Hash(password string) (string, error) {
	salt := make([]byte, saltLength)

	_, err := rand.Read(salt)
	if err != nil {
		return "", err
	}

	key := argon2.IDKey([]byte(password), salt, hashTime, hashMemory, hashThreads, keyLength)

	return fmt.Sprintf(
		"$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version, hashMemory, hashTime, hashThreads,
		encoding.EncodeToString(salt), encoding.EncodeToString(key),
	), nil
}

// Verify compares a password against a PHC formatted Argon2id hash.
func Verify(hash, password string) (bool, error) {
	parts := strings.Split(hash, "$")
	if len(parts) != 6 || parts[0] != "" || parts[1] != "argon2id" {
		return false, ErrInvalidHash
	}

	var version int

	_, err := fmt.Sscanf(parts[2], "v=%d", &version)
	if err != nil || version != argon2.Version {
		return false, ErrInvalidHash
	}

	memory, iterations, threads, err := parameters(parts[3])
	if err != nil {
		return false, err
	}

	salt, err := encoding.DecodeString(parts[4])
	if err != nil {
		return false, ErrInvalidHash
	}

	expected, err := encoding.DecodeString(parts[5])
	if err != nil || len(expected) == 0 {
		return false, ErrInvalidHash
	}

	key := argon2.IDKey([]byte(password), salt, iterations, memory, threads, uint32(len(expected)))

	return subtle.ConstantTimeCompare(key, expected) == 1, nil
}

// Waste burns a comparable amount of work for unknown users so that response
// timing does not disclose which usernames exist.
func Waste() {
	argon2.IDKey([]byte("outboxd"), make([]byte, saltLength), hashTime, hashMemory, hashThreads, keyLength)
}

func parameters(value string) (memory uint32, iterations uint32, threads uint8, err error) {
	for pair := range strings.SplitSeq(value, ",") {
		key, raw, ok := strings.Cut(pair, "=")
		if !ok {
			return 0, 0, 0, ErrInvalidHash
		}

		number, parseErr := strconv.ParseUint(raw, 10, 32)
		if parseErr != nil {
			return 0, 0, 0, ErrInvalidHash
		}

		switch key {
		case "m":
			memory = uint32(number)
		case "t":
			iterations = uint32(number)
		case "p":
			threads = uint8(number)
		default:
			return 0, 0, 0, ErrInvalidHash
		}
	}

	if memory == 0 || iterations == 0 || threads == 0 {
		return 0, 0, 0, ErrInvalidHash
	}

	return memory, iterations, threads, nil
}

package queue

import (
	"container/heap"
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/coalaura/outboxd/internal/disk"
)

// Status is the delivery state of a single recipient.
type Status string

const (
	StatusPending Status = "pending"
	StatusSent    Status = "sent"
	StatusFailed  Status = "failed"
)

// Recipient is one envelope recipient and its delivery outcome.
type Recipient struct {
	Address string `json:"address"`
	Domain  string `json:"domain"`
	Status  Status `json:"status"`
	Detail  string `json:"detail,omitempty"`
}

// Envelope is the queued metadata for one accepted message.
type Envelope struct {
	ID          string      `json:"id"`
	Username    string      `json:"username"`
	Sender      string      `json:"sender"`
	Recipients  []Recipient `json:"recipients"`
	Size        int64       `json:"size"`
	Created     time.Time   `json:"created"`
	Attempts    int         `json:"attempts"`
	NextAttempt time.Time   `json:"next_attempt"`
	LastError   string      `json:"last_error,omitempty"`
	SMTPUTF8    bool        `json:"smtp_utf8,omitempty"`

	index int
}

// Queue is a durable, crash-safe spool of messages awaiting delivery.
type Queue struct {
	directory string
	dead      string

	mu      sync.Mutex
	pending schedule
	notify  chan struct{}
}

// Pending reports how many recipients still need a delivery attempt.
func (e *Envelope) Pending() int {
	var count int

	for i := range e.Recipients {
		if e.Recipients[i].Status == StatusPending {
			count++
		}
	}

	return count
}

// Len returns the number of messages waiting for delivery.
func (q *Queue) Len() int {
	q.mu.Lock()
	defer q.mu.Unlock()

	return q.pending.Len()
}

// Add durably stores a message and schedules it for immediate delivery.
func (q *Queue) Add(envelope *Envelope, data []byte) error {
	envelope.Size = int64(len(data))

	err := disk.Write(q.message(envelope.ID), data, 0600)
	if err != nil {
		return err
	}

	err = q.store(envelope)
	if err != nil {
		os.Remove(q.message(envelope.ID))

		return err
	}

	q.schedule(envelope)

	return nil
}

// Next blocks until a message is due for delivery or ctx is cancelled.
func (q *Queue) Next(ctx context.Context) (*Envelope, error) {
	timer := time.NewTimer(time.Hour)
	defer timer.Stop()

	for {
		q.mu.Lock()

		wait := time.Hour

		if q.pending.Len() > 0 {
			envelope := q.pending[0]

			delay := time.Until(envelope.NextAttempt)
			if delay <= 0 {
				heap.Pop(&q.pending)

				q.mu.Unlock()

				return envelope, nil
			}

			wait = delay
		}

		q.mu.Unlock()

		timer.Stop()
		timer.Reset(wait)

		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-q.notify:
		case <-timer.C:
		}
	}
}

// Retry persists the updated envelope and reschedules it.
func (q *Queue) Retry(envelope *Envelope) error {
	err := q.store(envelope)
	if err != nil {
		return err
	}

	q.schedule(envelope)

	return nil
}

// Finish removes a fully delivered message from the spool.
func (q *Queue) Finish(envelope *Envelope) error {
	return errors.Join(
		os.Remove(q.metadata(envelope.ID)),
		os.Remove(q.message(envelope.ID)),
		disk.Sync(q.directory),
	)
}

// Bury moves an undeliverable message into the dead-letter directory.
func (q *Queue) Bury(envelope *Envelope) error {
	err := q.store(envelope)
	if err != nil {
		return err
	}

	return errors.Join(
		os.Rename(q.metadata(envelope.ID), filepath.Join(q.dead, envelope.ID+".json")),
		os.Rename(q.message(envelope.ID), filepath.Join(q.dead, envelope.ID+".eml")),
		disk.Sync(q.directory),
		disk.Sync(q.dead),
	)
}

// Reader opens the stored message for streaming to a destination.
func (q *Queue) Reader(id string) (*os.File, error) {
	return os.OpenFile(q.message(id), os.O_RDONLY, 0)
}

func (q *Queue) schedule(envelope *Envelope) {
	q.mu.Lock()
	heap.Push(&q.pending, envelope)
	q.mu.Unlock()

	select {
	case q.notify <- struct{}{}:
	default:
	}
}

func (q *Queue) store(envelope *Envelope) error {
	body, err := json.Marshal(envelope)
	if err != nil {
		return err
	}

	return disk.Write(q.metadata(envelope.ID), body, 0600)
}

func (q *Queue) message(id string) string {
	return filepath.Join(q.directory, id+".eml")
}

func (q *Queue) metadata(id string) string {
	return filepath.Join(q.directory, id+".json")
}

// Open loads an existing spool directory, creating it when needed.
func Open(directory string) (*Queue, error) {
	q := &Queue{
		directory: directory,
		dead:      filepath.Join(directory, "dead"),
		notify:    make(chan struct{}, 1),
	}

	err := disk.Mkdir(q.directory)
	if err != nil {
		return nil, err
	}

	err = disk.Mkdir(q.dead)
	if err != nil {
		return nil, err
	}

	entries, err := os.ReadDir(q.directory)
	if err != nil {
		return nil, err
	}

	metadata := make(map[string]struct{}, len(entries))

	for _, entry := range entries {
		name := entry.Name()

		if entry.IsDir() || !strings.HasSuffix(name, ".json") {
			continue
		}

		metadata[strings.TrimSuffix(name, ".json")] = struct{}{}

		envelope, err := read(filepath.Join(q.directory, name))
		if err != nil {
			continue
		}

		_, err = os.Stat(q.message(envelope.ID))
		if err != nil {
			os.Remove(q.metadata(envelope.ID))

			continue
		}

		heap.Push(&q.pending, envelope)
	}

	for _, entry := range entries {
		name := entry.Name()

		if entry.IsDir() || !strings.HasSuffix(name, ".eml") {
			continue
		}

		if _, ok := metadata[strings.TrimSuffix(name, ".eml")]; !ok {
			os.Remove(filepath.Join(q.directory, name))
		}
	}

	return q, nil
}

func read(path string) (*Envelope, error) {
	body, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	envelope := new(Envelope)

	err = json.Unmarshal(body, envelope)
	if err != nil {
		return nil, err
	}

	return envelope, nil
}

package queue

type schedule []*Envelope

func (s schedule) Len() int {
	return len(s)
}

func (s schedule) Less(i, j int) bool {
	return s[i].NextAttempt.Before(s[j].NextAttempt)
}

func (s schedule) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
	s[i].index = i
	s[j].index = j
}

func (s *schedule) Push(value any) {
	envelope := value.(*Envelope)
	envelope.index = len(*s)

	*s = append(*s, envelope)
}

func (s *schedule) Pop() any {
	old := *s
	last := len(old) - 1

	envelope := old[last]
	old[last] = nil

	*s = old[:last]

	return envelope
}

package records

import (
	"bytes"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/disk"
)

const maxString = 255

// Record is a single DNS entry the operator has to publish.
type Record struct {
	Name    string
	Type    string
	Value   string
	Purpose string
}

// Build returns every DNS record needed for the configured domain.
func Build(cfg *config.Config, dkim string) []Record {
	hostname := cfg.Server.Hostname + "."
	domain := cfg.Server.Domain + "."

	records := make([]Record, 0, 6)

	if cfg.DNS.PublicIPv4 != "" {
		records = append(records, Record{
			Name:    hostname,
			Type:    "A",
			Value:   cfg.DNS.PublicIPv4,
			Purpose: "Public IPv4 address of the SMTP hostname",
		})
	}

	if cfg.DNS.PublicIPv6 != "" {
		records = append(records, Record{
			Name:    hostname,
			Type:    "AAAA",
			Value:   cfg.DNS.PublicIPv6,
			Purpose: "Public IPv6 address of the SMTP hostname",
		})
	}

	records = append(records, Record{
		Name:    domain,
		Type:    "TXT",
		Value:   spf(cfg),
		Purpose: "SPF; authorizes this server to send for the domain and rejects everything else",
	})

	records = append(records, Record{
		Name:    hostname,
		Type:    "TXT",
		Value:   spf(cfg),
		Purpose: "SPF for the EHLO name; receivers check the HELO identity separately from the envelope sender",
	})

	records = append(records, Record{
		Name:    fmt.Sprintf("%s._domainkey.%s", cfg.DKIM.Selector, domain),
		Type:    "TXT",
		Value:   dkim,
		Purpose: "DKIM public key matching the generated private key",
	})

	records = append(records, Record{
		Name:    "_dmarc." + domain,
		Type:    "TXT",
		Value:   dmarc(cfg),
		Purpose: "DMARC policy; \"quarantine\" is a safe default; move to \"reject\" once reports look clean",
	})

	for _, host := range external(cfg) {
		records = append(records, Record{
			Name:    fmt.Sprintf("%s_report._dmarc.%s.", domain, host),
			Type:    "TXT",
			Value:   "v=DMARC1",
			Purpose: fmt.Sprintf("authorizes %s to receive DMARC reports for %s", host, cfg.Server.Domain),
		})
	}

	if cfg.DNS.ReportURI != "" {
		records = append(records, Record{
			Name:    "_smtp._tls." + domain,
			Type:    "TXT",
			Value:   fmt.Sprintf("v=TLSRPTv1; rua=%s", cfg.DNS.ReportURI),
			Purpose: "optional TLS reporting endpoint",
		})
	}

	return records
}

// Write renders the DNS instructions next to the other generated files.
func Write(cfg *config.Config, dkim string) (string, []byte, error) {
	var buffer bytes.Buffer

	buffer.Grow(4096)

	fmt.Fprintf(&buffer, "DNS setup for %s (%s)\n", cfg.Server.Domain, time.Now().Format(time.RFC3339))

	buffer.WriteString("- Outbound TCP port 25 (sending mail) must be open\n")
	buffer.WriteString("- Inbound TCP port 465 (implicit TLS) must be open\n")
	buffer.WriteString("- Inbound TCP port 587 (STARTTLS) must be open\n")

	if cfg.DNS.PublicIPv4 != "" {
		fmt.Fprintf(&buffer, "- PTR for %s must resolve to %s, and %s must resolve back to %s\n", cfg.DNS.PublicIPv4, cfg.Server.Hostname, cfg.Server.Hostname, cfg.DNS.PublicIPv4)
	}

	if cfg.DNS.PublicIPv6 != "" {
		fmt.Fprintf(&buffer, "- PTR for %s must resolve to %s; drop the AAAA record until it does\n", cfg.DNS.PublicIPv6, cfg.Server.Hostname)
	}

	buffer.WriteString("- PTR records are set at the hosting provider, not in this zone\n")
	fmt.Fprintf(&buffer, "- %s needs an MX pointing at a mailbox that accepts bounces and replies;\n  receivers reject mail whose envelope sender cannot be bounced to\n", cfg.Server.Domain)
	buffer.WriteString("- TXT values above 255 characters are shown pre-split; keep the quoting as-is\n")

	if cfg.TLS.Mode == "self_signed" {
		buffer.WriteString("- Replace self-signed submission certificate\n")
	}

	records := Build(cfg, dkim)

	for i, record := range records {
		buffer.WriteByte('\n')

		fmt.Fprintf(&buffer, "%d. %s\n", i+1, record.Purpose)
		fmt.Fprintf(&buffer, "  name  %s\n", record.Name)
		fmt.Fprintf(&buffer, "  type  %s\n", record.Type)

		if record.Type == "TXT" {
			fmt.Fprintf(&buffer, "  value %s\n", quote(record.Value))
		} else {
			fmt.Fprintf(&buffer, "  value %s\n", record.Value)
		}
	}

	path := cfg.ResolvePath(cfg.DNS.OutputFile)
	body := buffer.Bytes()

	return path, body, disk.Write(path, body, 0644)
}

func quote(value string) string {
	if len(value) <= maxString {
		return strconv.Quote(value)
	}

	var builder strings.Builder

	for start := 0; start < len(value); start += maxString {
		if start > 0 {
			builder.WriteByte(' ')
		}

		builder.WriteString(strconv.Quote(value[start:min(start+maxString, len(value))]))
	}

	return builder.String()
}

func spf(cfg *config.Config) string {
	var builder strings.Builder

	builder.WriteString("v=spf1")

	if cfg.DNS.PublicIPv4 != "" {
		fmt.Fprintf(&builder, " ip4:%s", cfg.DNS.PublicIPv4)
	}

	if cfg.DNS.PublicIPv6 != "" {
		fmt.Fprintf(&builder, " ip6:%s", cfg.DNS.PublicIPv6)
	}

	builder.WriteString(" -all")

	return builder.String()
}

func dmarc(cfg *config.Config) string {
	var builder strings.Builder

	fmt.Fprintf(&builder, "v=DMARC1; p=%s; sp=%s; np=reject; adkim=r; aspf=r", cfg.DNS.DMARC, cfg.DNS.DMARC)

	if cfg.DNS.ReportURI != "" {
		fmt.Fprintf(&builder, "; rua=%s", cfg.DNS.ReportURI)
	}

	return builder.String()
}

func external(cfg *config.Config) []string {
	var domains []string

	for uri := range strings.SplitSeq(cfg.DNS.ReportURI, ",") {
		address, ok := strings.CutPrefix(strings.TrimSpace(uri), "mailto:")
		if !ok {
			continue
		}

		address, _, _ = strings.Cut(address, "!")

		at := strings.LastIndexByte(address, '@')
		if at < 0 {
			continue
		}

		host := strings.ToLower(strings.TrimSuffix(address[at+1:], "."))

		if host == "" || host == cfg.Server.Domain || strings.HasSuffix(host, "."+cfg.Server.Domain) {
			continue
		}

		if !slices.Contains(domains, host) {
			domains = append(domains, host)
		}
	}

	return domains
}

package sign

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"errors"
	"fmt"
	"os"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/disk"
	"github.com/emersion/go-msgauth/dkim"
)

const keyBits = 2048

// Signer produces DKIM-Signature header fields for outgoing messages.
type Signer struct {
	options dkim.SignOptions

	// PublicKey is the base64 SubjectPublicKeyInfo used in the DNS record.
	PublicKey string
}

// Ensure loads the DKIM key, generating one when it does not exist yet.
func Ensure(cfg *config.Config) (*Signer, bool, error) {
	path := cfg.ResolvePath(cfg.DKIM.PrivateKeyFile)

	key, created, err := ensureKey(path)
	if err != nil {
		return nil, false, err
	}

	public, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
	if err != nil {
		return nil, false, err
	}

	return &Signer{
		options: dkim.SignOptions{
			Domain:                 cfg.Server.Domain,
			Selector:               cfg.DKIM.Selector,
			Signer:                 key,
			Hash:                   crypto.SHA256,
			HeaderCanonicalization: dkim.CanonicalizationRelaxed,
			BodyCanonicalization:   dkim.CanonicalizationRelaxed,
			HeaderKeys:             cfg.DKIM.Headers,
		},
		PublicKey: base64.StdEncoding.EncodeToString(public),
	}, created, nil
}

// Signature returns the DKIM-Signature field, including its trailing CRLF, for
// a message that is already CRLF normalized.
func (s *Signer) Signature(message []byte) (string, error) {
	signer, err := dkim.NewSigner(&s.options)
	if err != nil {
		return "", err
	}

	_, err = signer.Write(message)
	if err != nil {
		signer.Close()

		return "", err
	}

	err = signer.Close()
	if err != nil {
		return "", err
	}

	return signer.Signature(), nil
}

// Record returns the DKIM TXT record value for the generated key.
func (s *Signer) Record() string {
	return fmt.Sprintf("v=DKIM1; k=rsa; h=sha256; p=%s", s.PublicKey)
}

func ensureKey(path string) (*rsa.PrivateKey, bool, error) {
	body, err := os.ReadFile(path)
	if err == nil {
		key, err := parseKey(body)

		return key, false, err
	}

	if !errors.Is(err, os.ErrNotExist) {
		return nil, false, err
	}

	key, err := rsa.GenerateKey(rand.Reader, keyBits)
	if err != nil {
		return nil, false, err
	}

	encoded, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, false, err
	}

	err = disk.WriteExclusive(path, pem.EncodeToMemory(&pem.Block{
		Type:  "PRIVATE KEY",
		Bytes: encoded,
	}), 0600)

	if err != nil {
		return nil, false, err
	}

	return key, true, nil
}

func parseKey(body []byte) (*rsa.PrivateKey, error) {
	block, _ := pem.Decode(body)
	if block == nil {
		return nil, errors.New("dkim private key is not PEM encoded")
	}

	switch block.Type {
	case "RSA PRIVATE KEY":
		return x509.ParsePKCS1PrivateKey(block.Bytes)
	case "PRIVATE KEY":
		parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}

		key, ok := parsed.(*rsa.PrivateKey)
		if !ok {
			return nil, fmt.Errorf("unsupported dkim key type %T", parsed)
		}

		return key, nil
	}

	return nil, fmt.Errorf("unsupported PEM block %q", block.Type)
}

package smtpd

import (
	"sync"
	"time"
)

const (
	freeAttempts = 5
	lockoutBase  = 2 * time.Second
	lockoutMax   = 5 * time.Minute
	entryExpiry  = 30 * time.Minute
)

type attempts struct {
	failures int
	until    time.Time
	seen     time.Time
}

type limiter struct {
	mu      sync.Mutex
	entries map[string]*attempts
	pruned  time.Time
}

func newLimiter() *limiter {
	return &limiter{
		entries: make(map[string]*attempts),
		pruned:  time.Now(),
	}
}

func (l *limiter) allow(ip string) bool {
	now := time.Now()

	l.mu.Lock()
	defer l.mu.Unlock()

	l.prune(now)

	entry, ok := l.entries[ip]
	if !ok {
		return true
	}

	entry.seen = now

	return now.After(entry.until)
}

func (l *limiter) failed(ip string) {
	now := time.Now()

	l.mu.Lock()
	defer l.mu.Unlock()

	entry, ok := l.entries[ip]
	if !ok {
		entry = new(attempts)
		l.entries[ip] = entry
	}

	entry.failures++
	entry.seen = now

	if entry.failures <= freeAttempts {
		return
	}

	lockout := lockoutBase << min(entry.failures-freeAttempts-1, 10)
	entry.until = now.Add(min(lockout, lockoutMax))
}

func (l *limiter) succeeded(ip string) {
	l.mu.Lock()
	delete(l.entries, ip)
	l.mu.Unlock()
}

func (l *limiter) prune(now time.Time) {
	if now.Sub(l.pruned) < entryExpiry {
		return
	}

	l.pruned = now

	for ip, entry := range l.entries {
		if now.Sub(entry.seen) > entryExpiry {
			delete(l.entries, ip)
		}
	}
}

package smtpd

import (
	"github.com/emersion/go-sasl"
)

// PLAIN over TLS is equivalent and preferred.
const mechLogin = "LOGIN"

const (
	loginStateInit = iota
	loginStateUsername
	loginStatePassword
	loginStateDone
)

var (
	loginUsername = []byte("Username:")
	loginPassword = []byte("Password:")
)

type loginServer struct {
	authenticate func(username, password string) error

	username string
	state    int
}

func newLoginServer(authenticate func(username, password string) error) sasl.Server {
	return &loginServer{authenticate: authenticate}
}

func (s *loginServer) Next(response []byte) (challenge []byte, done bool, err error) {
	if s.state == loginStateInit {
		s.state = loginStateUsername

		if len(response) == 0 {
			return loginUsername, false, nil
		}
	}

	switch s.state {
	case loginStateUsername:
		if len(response) == 0 {
			s.state = loginStateDone

			return nil, true, sasl.ErrUnexpectedClientResponse
		}

		s.username = string(response)
		s.state = loginStatePassword

		return loginPassword, false, nil
	case loginStatePassword:
		s.state = loginStateDone

		return nil, true, s.authenticate(s.username, string(response))
	}

	return nil, true, sasl.ErrUnexpectedClientResponse
}

package smtpd

import (
	"sync"
	"time"
)

type submissionAllowance struct {
	messages   float64
	recipients float64
	updated    time.Time
}

type submissionLimiter struct {
	maxMessages   int
	maxRecipients int

	mu      sync.Mutex
	entries map[string]*submissionAllowance
}

func newSubmissionLimiter(maxMessages, maxRecipients int) *submissionLimiter {
	return &submissionLimiter{
		maxMessages:   maxMessages,
		maxRecipients: maxRecipients,
		entries:       make(map[string]*submissionAllowance),
	}
}

func (l *submissionLimiter) take(username string, recipients int) bool {
	now := time.Now()

	l.mu.Lock()
	defer l.mu.Unlock()

	allowance, ok := l.entries[username]
	if !ok {
		allowance = &submissionAllowance{
			messages:   float64(l.maxMessages),
			recipients: float64(l.maxRecipients),
			updated:    now,
		}

		l.entries[username] = allowance
	}

	l.refill(allowance, now)

	if allowance.messages < 1 || allowance.recipients < float64(recipients) {
		return false
	}

	allowance.messages--
	allowance.recipients -= float64(recipients)

	return true
}

func (l *submissionLimiter) refund(username string, recipients int) {
	now := time.Now()

	l.mu.Lock()
	defer l.mu.Unlock()

	allowance, ok := l.entries[username]
	if !ok {
		return
	}

	l.refill(allowance, now)

	allowance.messages = min(allowance.messages+1, float64(l.maxMessages))
	allowance.recipients = min(allowance.recipients+float64(recipients), float64(l.maxRecipients))
}

func (l *submissionLimiter) refill(allowance *submissionAllowance, now time.Time) {
	elapsed := now.Sub(allowance.updated)

	allowance.updated = now

	if elapsed <= 0 {
		return
	}

	hours := elapsed.Hours()

	allowance.messages = min(
		allowance.messages+hours*float64(l.maxMessages),
		float64(l.maxMessages),
	)

	allowance.recipients = min(
		allowance.recipients+hours*float64(l.maxRecipients),
		float64(l.maxRecipients),
	)
}

package smtpd

import (
	"fmt"
	"io"
	"slices"
	"strings"
	"time"

	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/message"
	"github.com/coalaura/outboxd/internal/passwd"
	"github.com/coalaura/outboxd/internal/queue"
	"github.com/emersion/go-sasl"
	"github.com/emersion/go-smtp"
)

type session struct {
	server *Server
	conn   *smtp.Conn

	user       config.User
	sender     string
	recipients []string
	smtpUTF8   bool
}

func (s *session) AuthMechanisms() []string {
	return []string{sasl.Plain, mechLogin}
}

func (s *session) Auth(mech string) (sasl.Server, error) {
	if !s.secure() {
		return nil, smtp.ErrAuthUnsupported
	}

	switch mech {
	case sasl.Plain:
		return sasl.NewPlainServer(func(identity, username, password string) error {
			if identity != "" && identity != username {
				return smtp.ErrAuthFailed
			}

			return s.authenticate(username, password)
		}), nil
	case mechLogin:
		return newLoginServer(s.authenticate), nil
	}

	return nil, smtp.ErrAuthUnknownMechanism
}

func (s *session) Mail(from string, opts *smtp.MailOptions) error {
	if s.user.Username == "" {
		return smtp.ErrAuthRequired
	}

	address, err := address(from)
	if err != nil {
		return &smtp.SMTPError{
			Code:         501,
			EnhancedCode: smtp.EnhancedCode{5, 1, 7},
			Message:      "Invalid sender address",
		}
	}

	if !s.user.Allows(address) {
		s.server.log.Printf("rejected sender %q for user %q\n", address, s.user.Username)

		return &smtp.SMTPError{
			Code:         550,
			EnhancedCode: smtp.EnhancedCode{5, 7, 1},
			Message:      "Sender address not allowed for this account",
		}
	}

	s.sender = address
	s.recipients = s.recipients[:0]
	s.smtpUTF8 = opts != nil && opts.UTF8

	return nil
}

func (s *session) Rcpt(to string, opts *smtp.RcptOptions) error {
	if s.sender == "" {
		return &smtp.SMTPError{
			Code:         503,
			EnhancedCode: smtp.EnhancedCode{5, 5, 1},
			Message:      "MAIL FROM required first",
		}
	}

	address, err := address(to)

	var domain string

	if err == nil {
		domain = address[strings.LastIndexByte(address, '@')+1:]
	}

	if err != nil || !strings.Contains(domain, ".") || strings.HasPrefix(domain, "[") {
		return &smtp.SMTPError{
			Code:         501,
			EnhancedCode: smtp.EnhancedCode{5, 1, 3},
			Message:      "Invalid recipient address",
		}
	}

	// RFC 5321 lets a client repeat a recipient.
	if slices.Contains(s.recipients, address) {
		return nil
	}

	s.recipients = append(s.recipients, address)

	return nil
}

func (s *session) Data(r io.Reader) error {
	// go-smtp expects the reader to be consumed even on failure.
	defer io.Copy(io.Discard, r)

	if s.sender == "" || len(s.recipients) == 0 {
		return &smtp.SMTPError{
			Code:         503,
			EnhancedCode: smtp.EnhancedCode{5, 5, 1},
			Message:      "No valid recipients",
		}
	}

	var remoteAddress string

	if s.server.cfg.Server.IncludeClientIPInReceived {
		remoteAddress = host(s.conn)
	}

	prepared, err := message.Prepare(r, message.Options{
		Hostname: s.server.cfg.Server.Hostname,
		Helo:     s.conn.Hostname(),
		Remote:   remoteAddress,
		TLS:      s.tls(),
	})

	if err != nil {
		return &smtp.SMTPError{
			Code:         550,
			EnhancedCode: smtp.EnhancedCode{5, 6, 0},
			Message:      responseText(err.Error()),
		}
	}

	if !s.user.Allows(prepared.From) {
		s.server.log.Printf("rejected From header %q for user %q\n", prepared.From, s.user.Username)

		return &smtp.SMTPError{
			Code:         550,
			EnhancedCode: smtp.EnhancedCode{5, 7, 1},
			Message:      "From header not allowed for this account",
		}
	}

	if !s.server.rates.take(s.user.Username, len(s.recipients)) {
		s.server.log.Printf("rate-limited submission for user %q\n", s.user.Username)

		return errSubmissionRate
	}

	var accepted bool

	defer func() {
		if !accepted {
			s.server.rates.refund(s.user.Username, len(s.recipients))
		}
	}()

	signature, err := s.server.signer.Signature(prepared.Data)
	if err != nil {
		s.server.log.Printf("dkim signing failed: %v\n", err)

		return errTemporaryFailure
	}

	data := make([]byte, 0, len(signature)+len(prepared.Data))
	data = append(data, signature...)
	data = append(data, prepared.Data...)

	envelope := &queue.Envelope{
		ID:          identifier(),
		Username:    s.user.Username,
		Sender:      s.sender,
		Recipients:  make([]queue.Recipient, 0, len(s.recipients)),
		Created:     time.Now(),
		NextAttempt: time.Now(),
		SMTPUTF8:    s.smtpUTF8,
	}

	for _, recipient := range s.recipients {
		envelope.Recipients = append(envelope.Recipients, queue.Recipient{
			Address: recipient,
			Domain:  recipient[strings.LastIndexByte(recipient, '@')+1:],
			Status:  queue.StatusPending,
		})
	}

	err = s.server.queue.Add(envelope, data)
	if err != nil {
		s.server.log.Printf("failed to queue message: %v\n", err)

		return errTemporaryFailure
	}

	accepted = true

	s.server.log.Printf("queued %s from %s for %d recipient(s)\n", envelope.ID, s.sender, len(envelope.Recipients))

	return nil
}

func (s *session) Reset() {
	s.sender = ""
	s.recipients = s.recipients[:0]
	s.smtpUTF8 = false
}

func (s *session) Logout() error {
	return nil
}

func (s *session) authenticate(username, password string) error {
	ip := host(s.conn)

	if !s.server.limiter.allow(ip) {
		s.server.log.Printf("throttled authentication from %s\n", ip)

		return smtp.ErrAuthFailed
	}

	s.server.hashing <- struct{}{}
	defer func() { <-s.server.hashing }()

	user, ok := s.server.cfg.User(username)
	if !ok || !user.Enabled {
		passwd.Waste()
		s.server.limiter.failed(ip)

		return smtp.ErrAuthFailed
	}

	valid, err := passwd.Verify(user.PasswordHash, password)
	if err != nil {
		s.server.log.Printf("user %q has an unusable password hash: %v\n", user.Username, err)
	}

	if !valid {
		s.server.limiter.failed(ip)

		return smtp.ErrAuthFailed
	}

	s.server.limiter.succeeded(ip)
	s.user = user

	return nil
}

func (s *session) secure() bool {
	_, ok := s.conn.TLSConnectionState()

	return ok
}

func (s *session) tls() string {
	state, ok := s.conn.TLSConnectionState()
	if !ok {
		return ""
	}

	return fmt.Sprintf("TLS%x", state.Version)
}

package smtpd

import (
	"context"
	"crypto/rand"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"net/mail"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/coalaura/outboxd/internal/certs"
	"github.com/coalaura/outboxd/internal/config"
	"github.com/coalaura/outboxd/internal/queue"
	"github.com/coalaura/outboxd/internal/sign"
	"github.com/emersion/go-smtp"
)

var (
	errTemporaryFailure = &smtp.SMTPError{
		Code:         451,
		EnhancedCode: smtp.EnhancedCode{4, 3, 0},
		Message:      "Temporary failure, try again later",
	}

	errSubmissionRate = &smtp.SMTPError{
		Code:         452,
		EnhancedCode: smtp.EnhancedCode{4, 7, 0},
		Message:      "Submission rate limit exceeded, try again later",
	}
)

const (
	SubmissionPort  = ":587"
	ImplicitTLSPort = ":465"

	maxResponseLength = 256
)

// Logger receives operational messages.
type Logger interface {
	Printf(format string, values ...any)
	Println(values ...any)
}

// Server runs both submission listeners against a shared backend.
type Server struct {
	cfg    *config.Config
	queue  *queue.Queue
	signer *sign.Signer
	log    Logger

	limiter *limiter
	rates   *submissionLimiter

	// Bounds concurrent Argon2id derivations so authentication floods cannot
	// exhaust memory.
	hashing chan struct{}

	starttls *smtp.Server
	implicit *smtp.Server

	starttlsListener net.Listener
	implicitListener net.Listener
}

// New builds the submission server.
func New(cfg *config.Config, keeper *certs.Keeper, signer *sign.Signer, spool *queue.Queue, log Logger) *Server {
	srv := &Server{
		cfg:     cfg,
		queue:   spool,
		signer:  signer,
		log:     log,
		limiter: newLimiter(),
		rates:   newSubmissionLimiter(cfg.Server.MaxMessagesPerHour, cfg.Server.MaxRecipientsPerHour),
		hashing: make(chan struct{}, 4),
	}

	srv.starttls = srv.listener(cfg, keeper)
	srv.implicit = srv.listener(cfg, keeper)

	srv.starttls.Addr = SubmissionPort
	srv.implicit.Addr = ImplicitTLSPort

	return srv
}

// Listen opens both submission listeners without starting their accept loops.
func (s *Server) Listen() error {
	if s.starttlsListener != nil || s.implicitListener != nil {
		return errors.New("submission listeners are already open")
	}

	starttlsListener, err := net.Listen("tcp", s.starttls.Addr)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", s.starttls.Addr, err)
	}

	implicitListener, err := net.Listen("tcp", s.implicit.Addr)
	if err != nil {
		starttlsListener.Close()

		return fmt.Errorf("listen on %s: %w", s.implicit.Addr, err)
	}

	s.starttlsListener = starttlsListener
	s.implicitListener = implicitListener

	s.log.Printf(
		"Listening for submission on %s (STARTTLS) and %s (implicit TLS)\n",
		s.starttls.Addr,
		s.implicit.Addr,
	)

	return nil
}

// Run serves both listeners until ctx is cancelled.
func (s *Server) Run(ctx context.Context) error {
	if s.starttlsListener == nil || s.implicitListener == nil {
		return errors.New("submission listeners are not open")
	}

	var (
		wg     sync.WaitGroup
		errs   [2]error
		closer sync.Once
	)

	stop := func() {
		closer.Do(func() {
			shutdown, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
			defer cancel()

			s.starttls.Shutdown(shutdown)
			s.implicit.Shutdown(shutdown)
		})
	}

	wg.Go(func() {
		errs[0] = ignoreClosed(s.starttls.Serve(s.starttlsListener))

		stop()
	})

	wg.Go(func() {
		listener := tls.NewListener(s.implicitListener, s.implicit.TLSConfig)

		errs[1] = ignoreClosed(s.implicit.Serve(listener))

		stop()
	})

	wg.Go(func() {
		<-ctx.Done()

		stop()
	})

	wg.Wait()

	return errors.Join(errs[0], errs[1])
}

func (s *Server) listener(cfg *config.Config, keeper *certs.Keeper) *smtp.Server {
	server := smtp.NewServer(smtp.BackendFunc(s.session))

	server.Domain = cfg.Server.Hostname
	server.TLSConfig = keeper.Config()
	server.MaxMessageBytes = cfg.Server.MaxMessageBytes
	server.MaxRecipients = cfg.Server.MaxRecipients
	server.ReadTimeout = config.Duration(cfg.Server.ReadTimeout)
	server.WriteTimeout = config.Duration(cfg.Server.WriteTimeout)
	server.AllowInsecureAuth = false
	server.EnableSMTPUTF8 = true
	server.ErrorLog = s.log

	return server
}

func (s *Server) session(c *smtp.Conn) (smtp.Session, error) {
	return &session{
		server: s,
		conn:   c,
	}, nil
}

func address(value string) (string, error) {
	value = strings.TrimSpace(value)

	parsed, err := mail.ParseAddress(value)
	if err != nil {
		return "", err
	}

	if parsed.Address != value {
		return "", errors.New("address contains a display name")
	}

	return strings.ToLower(parsed.Address), nil
}

func identifier() string {
	return strconv.FormatInt(time.Now().UnixNano(), 36) + "-" + strings.ToLower(rand.Text()[:10])
}

func remote(c *smtp.Conn) string {
	addr := c.Conn().RemoteAddr()
	if addr == nil {
		return "unknown"
	}

	return addr.String()
}

func host(c *smtp.Conn) string {
	addr := c.Conn().RemoteAddr()
	if addr == nil {
		return "unknown"
	}

	ip, _, err := net.SplitHostPort(addr.String())
	if err != nil {
		return addr.String()
	}

	return ip
}

func ignoreClosed(err error) error {
	if err == nil || errors.Is(err, net.ErrClosed) || errors.Is(err, smtp.ErrServerClosed) {
		return nil
	}

	return err
}

func responseText(value string) string {
	value = strings.Map(func(char rune) rune {
		if char < 32 || char > 126 {
			return ' '
		}

		return char
	}, value)

	value = strings.Join(strings.Fields(value), " ")

	if value == "" {
		return "Invalid message"
	}

	if len(value) > maxResponseLength {
		return value[:maxResponseLength]
	}

	return value
}
